200	// ====== 可用行动列表 ======
201	function getAvailableActions(state) {
202	  const actions = [];
203	
204	  // 提升为函数级变量（用 let，块内可重新指向用 const）
205	  const locKey = state.trade.currentLocation;
206	
207	  if (state.player.phase === "street") {
208	    // --- 街头阶段行动 ---
209	
210	    // 1. 工作
211	    const jobIds = getJobsAtLocation(locKey);
212	    for (const jobId of jobIds) {
213	      const job = getJobById(jobId);
214	      if (!job) continue;
215	      const reqFail = checkJobRequirements(job, state);
216	      const payEstimate = reqFail ? null : estimateJobPay(job, state);
217	
218	      actions.push({
219	        id: "job_" + jobId,
220	        name: job.name,
221	        desc: job.desc,
222	        icon: job.icon,
223	        payEstimate: payEstimate
224	          ? `${payEstimate - (job.startupCost || 0)}~${payEstimate + Math.floor(payEstimate * 0.3)}`
225	          : null,
226	        costEstimate: job.startupCost || null,
227	        reqFail,
228	        disabled:
229	          !!reqFail ||
230	          (job.startupCost && state.resources.cash < job.startupCost
231	            ? `启动资金不足(需¥${job.startupCost})`
232	            : null) ||
233	          null,
234	        handler: () => {
235	          const finalReq = checkJobRequirements(job, state);
236	          if (finalReq) {
237	            StateManager.addMessage(`⚠️ ${finalReq}`, "warning");
238	            return;
239	          }
240	          if (job.startupCost && state.resources.cash < job.startupCost) {
241	            StateManager.addMessage(
242	              `⚠️ 启动资金不足，需要 ¥${job.startupCost}`,
243	              "warning",
244	            );
245	            return;
246	          }
247	          doStreetJob(job);
248	        },
249	      });
250	    }
251	
252	    // 如果没有可用工作
253	    if (jobIds.length === 0) {
254	      actions.push({
255	        id: "no_jobs",
256	        name: "当前地点没有工作机会",
257	        desc: "尝试旅行到其他地点寻找工作。",
258	        icon: "🚫",
259	        disabled: true,
260	      });
261	    }
262	
263	    // 批发市场 — 批发进货
264	    if (locKey === "wholesaleMarket") {
265	      actions.push({
266	        id: "wholesale_header",
267	        name: "📦 批发进货（转到交易Tab）",
268	        desc: "在批发市场以折扣价批量购入商品，转手到商业区卖出赚差价！",
269	        icon: "📦",
270	        handler: () => {
271	          switchTab("trade");
272	        },
273	      });
274	    }
275	
276	    // 零售买卖 — 在任何有价格数据的地点都可以买卖
277	    if (
278	      state.trade.goodsPrices[locKey] &&
279	      Object.keys(state.trade.goodsPrices[locKey]).length > 0
280	    ) {
281	      actions.push({
282	        id: "trade_header",
283	        name: "🛒 买卖商品（转到交易Tab）",
284	        desc: "查看当前市场价格，低买高卖赚取差价。",
285	        icon: "🛒",
286	        handler: () => {
287	          switchTab("trade");
288	        },
289	      });
290	    }
291	
292	    // === 住所系统 ===
293	    if (locKey === "slum") {
294	      const currentTier = state.housing?.tier || 0;
295	      // HOUSING_TIERS 定义在 data/items.js 中（全局常量）
296	
297	      // 显示当前住所
298	      const curHouse = HOUSING_TIERS[currentTier];
299	      actions.push({
300	        id: "housing_current",
301	        name: `${curHouse.icon} 当前住所：${curHouse.name}`,
302	        desc: `容量+${curHouse.capacity} | 睡眠恢复疲劳-${curHouse.fatigueRecovery} | ${curHouse.desc}${curHouse.rent > 0 ? ` | 日租¥${curHouse.rent}/天` : ""}`,
303	        icon: curHouse.icon,
304	        disabled: true,
305	      });
306	
307	      // 可升级的住所
308	      for (let t = currentTier + 1; t < HOUSING_TIERS.length; t++) {
309	        const house = HOUSING_TIERS[t];
310	        const canAfford = state.resources.cash >= house.cost;
311	        actions.push({
312	          id: "housing_upgrade_" + t,
313	          name: `⬆️ 升级到${house.name}`,
314	          desc: `${house.desc} 一次性付¥${house.cost} + 日租¥${house.rent}/天`,
315	          icon: house.icon,
316	          costEstimate: house.cost,
317	          disabled: !canAfford,
318	          reqFail: !canAfford ? `需 ¥${house.cost}` : null,
319	          handler: () => {
320	            state.resources.cash -= house.cost;
321	            state.housing.tier = t;
322	            state.housing.rentedDay = state.player.day;
323	            state.inventory.capacity =
324	              house.capacity + (state.housing.storageCapacity || 0);
325	            StateManager.addMessage(
326	              `🏠 搬进了${house.name}！容量提升至${state.inventory.capacity}。`,
327	              "success",
328	            );
329	          },
330	        });
331	      }
332	    }
333	
334	    // === 仓库租赁（批发市场）===
335	    if (locKey === "wholesaleMarket") {
336	      const hasStorage = state.housing?.storageRented;
337	      const STORAGE_OPTIONS = [
338	        {
339	          id: "small",
340	          name: "小仓库",
341	          cost: 500,
342	          rent: 20,
343	          capacity: 150,
344	          icon: "📦",
345	        },
346	        {
347	          id: "big",
348	          name: "大仓库",
349	          cost: 1500,
350	          rent: 50,
351	          capacity: 500,
352	          icon: "🏗️",
353	        },
354	      ];
355	
356	      if (hasStorage) {
357	        actions.push({
358	          id: "storage_current",
359	          name: `📦 已租仓库 (额外+${state.housing.storageCapacity || 0}容量)`,
360	          desc: `日租¥${STORAGE_OPTIONS.find((s) => s.capacity === state.housing.storageCapacity)?.rent || "?"}/天`,
361	          icon: "📦",
362	          disabled: true,
363	        });
364	      } else {
365	        for (const opt of STORAGE_OPTIONS) {
366	          const canAfford = state.resources.cash >= opt.cost;
367	          actions.push({
368	            id: "storage_rent_" + opt.id,
369	            name: `📦 租用${opt.name}`,
370	            desc: `额外+${opt.capacity}商品存储容量。一次性¥${opt.cost} + 日租¥${opt.rent}/天`,
371	            icon: opt.icon,
372	            costEstimate: opt.cost,
373	            disabled: !canAfford,
374	            reqFail: !canAfford ? `需 ¥${opt.cost}` : null,
375	            handler: () => {
376	              state.resources.cash -= opt.cost;
377	              state.housing.storageRented = true;
378	              state.housing.storageCapacity = opt.capacity;
379	              const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
380	              state.inventory.capacity = baseCap + opt.capacity;
381	              StateManager.addMessage(
382	                `📦 租下了${opt.name}！总容量提升至${state.inventory.capacity}。`,
383	                "success",
384	              );
385	            },
386	          });
387	        }
388	      }
389	    }
390	
391	    // === 背包升级（商业区）===
392	    if (locKey === "commercialDist") {
393	      const BACKPACKS = [
394	        {
395	          id: "backpack_basic",
396	          name: "帆布背包",
397	          cost: 50,
398	          capacity: 5,
399	          icon: "🎒",
400	        },
401	        {
402	          id: "backpack_large",
403	          name: "大号旅行包",
404	          cost: 150,
405	          capacity: 15,
406	          icon: "🎒",
407	        },
408	        {
409	          id: "backpack_pro",
410	          name: "专业登山包",
411	          cost: 400,
412	          capacity: 30,
413	          icon: "🎒",
414	        },
415	      ];
416	      // 只显示未购买的
417	      const ownedPacks = state.inventory.items.filter((i) =>
418	        i.id.startsWith("backpack_"),
419	      );
420	      for (const pack of BACKPACKS) {
421	        if (ownedPacks.find((p) => p.id === pack.id)) continue;
422	        const canAfford = state.resources.cash >= pack.cost;
423	        actions.push({
424	          id: "buy_" + pack.id,
425	          name: `🛍️ 购买${pack.name}`,
426	          desc: `随身容量+${pack.capacity}。一次性购买，永久拥有。`,
427	          icon: pack.icon,
428	          costEstimate: pack.cost,
429	          disabled: !canAfford,
430	          handler: () => {
431	            state.resources.cash -= pack.cost;
432	            state.inventory.items.push({ id: pack.id, qty: 1 });
433	            state.inventory.capacity += pack.capacity;
434	            StateManager.addMessage(
435	              `🎒 购买了${pack.name}，随身容量+${pack.capacity}！`,
436	              "success",
437	            );
438	          },
439	        });
440	      }
441	    }
442	
443	    // 2. 旅行
444	    const reachable = getReachableLocations(locKey);
445	    for (const destKey of reachable) {
446	      const dest = getLocation(destKey);
447	      if (!dest) continue;
448	      actions.push({
449	        id: "travel_" + destKey,
450	        name: `前往 ${dest.name}`,
451	        desc: dest.desc,
452	        icon: "🚶",
453	        handler: () => {
454	          StateManager.update("trade.currentLocation", destKey);
455	          StateManager.addMessage(`🚶 你来到了${dest.name}。`, "info");
456	          consumeAP(15);
457	        },
458	      });
459	    }
460	
461	    // 3. 通用行动
462	    actions.push({
463	      id: "rest",
464	      name: "休息一会",
465	      desc: "找个地方坐坐，恢复一些疲劳。",
466	      icon: "😴",
467	      handler: () => {
468	        const state = StateManager.getState();
469	        const recovery = 25 + Math.floor(Math.random() * 15);
470	        state.needs.fatigue = Math.max(0, state.needs.fatigue - recovery);
471	        state.needs.happiness = Math.min(100, state.needs.happiness + 5);
472	        StateManager.addMessage(`😴 你休息了一会，疲劳-${recovery}。`, "info");
473	        consumeAP(15);
474	      },
475	    });
476	
477	    actions.push({
478	      id: "eat",
479	      name: "吃顿饭",
480	      desc: "花10元在路边摊吃个快餐，填饱肚子。",
481	      icon: "🍚",
482	      costEstimate: 10,
483	      disabled: state.resources.cash < 10 ? true : false,
484	      handler: () => {
485	        const st = StateManager.getState();
486	        if (st.resources.cash < 10) {
487	          StateManager.addMessage("⚠️ 钱不够吃饭了！", "danger");
488	          return;
489	        }
490	        st.resources.cash -= 10;
491	        st.needs.hunger = Math.min(100, st.needs.hunger + 35);
492	        st.needs.happiness = Math.min(100, st.needs.happiness + 8);
493	        StateManager.addMessage(
494	          "🍚 你花10元吃了顿饭，肚子饱了心情好了。",
495	          "success",
496	        );
497	        consumeAP(10);
498	      },
499	    });
500	
501	    actions.push({
502	      id: "shower",
503	      name: "洗澡",
504	      desc: "花5元去公共澡堂洗个澡。",
505	      icon: "🚿",
506	      costEstimate: 5,
507	      disabled: state.resources.cash < 5 ? true : false,
508	      handler: () => {
509	        const st = StateManager.getState();
510	        if (st.resources.cash < 5) {
511	          StateManager.addMessage("⚠️ 不够钱洗澡。", "danger");
512	          return;
513	        }
514	        st.resources.cash -= 5;
515	        st.needs.hygiene = Math.min(100, st.needs.hygiene + 40);
516	        StateManager.addMessage("🚿 洗了个澡，神清气爽。", "success");
517	        consumeAP(10);
518	      },
519	    });
520	
521	    // 银行相关行动
522	    if (locKey === "bank") {
523	      actions.push({
524	        id: "deposit",
525	        name: "存款",
526	        desc: "把钱存入银行，吃利息也更安全。",
527	        icon: "🏦",
528	        disabled: state.resources.cash <= 0 ? true : false,
529	        handler: () => {
530	          showDepositModal();
531	        },
532	      });
533	      actions.push({
534	        id: "withdraw",
535	        name: "取款",
536	        desc: "从银行取出存款。",
537	        icon: "💰",
538	        disabled: state.resources.bankBalance <= 0 ? true : false,
539	        handler: () => {
540	          showWithdrawModal();
541	        },
542	      });
543	      actions.push({
