1073	/** 消耗行动力，推进时间。每次行动调用此函数替代旧的 advanceTimeSlot() */
1074	function consumeAP(cost) {
1075	  const state = StateManager.getState();
1076	  state.player.actionPoints = Math.max(0, state.player.actionPoints - cost);
1077	
1078	  // 更新显示用的时段
1079	  const pct = state.player.actionPoints / state.player.maxActionPoints;
1080	  if (pct > 0.66) state.player.timeSlot = "morning";
1081	  else if (pct > 0.33) state.player.timeSlot = "afternoon";
1082	  else state.player.timeSlot = "evening";
1083	
1084	  // Per-action 随机事件判定 (6%基础概率)
1085	  if (!state._pendingEvent) {
1086	    const phase = state.player.phase === "corporate" ? "corporate" : "street";
1087	    if (Math.random() < 0.06) {
1088	      if (typeof queueRandomEvent === "function")
1089	        queueRandomEvent(state, phase);
1090	    }
1091	  }
1092	
1093	  // 行动力耗尽 → 结束一天
1094	  if (state.player.actionPoints <= 0) {
1095	    endDay();
1096	  }
1097	}
