1104	/**
1105	 * 渲染并展示一个事件模态框
1106	 * @param {Object} evt - 事件对象
1107	 */
1108	function showEventModal(evt) {
1109	  // 先卸掉任何旧弹窗
1110	  document.querySelector(".modal-overlay")?.remove();
1111	
1112	  // 构建选项HTML
1113	  const choicesHtml = evt.choices
1114	    .map((ch, i) => {
1115	      const hintStr = ch.hint
1116	        ? `<div class="choice-hint">${ch.hint}</div>`
1117	        : "";
1118	      // 检查现金是否够
1119	      let disabled = false;
1120	      if (ch.cost && StateManager.getState().resources.cash < ch.cost) {
1121	        disabled = true;
1122	      }
1123	      const costTag = ch.cost
1124	        ? ` <span style="color:var(--warning);font-size:11px;">需 ¥${ch.cost}</span>`
1125	        : "";
1126	      return `
1127	        <button class="event-choice ${disabled ? "disabled" : ""}" data-idx="${i}" ${disabled ? "disabled" : ""}>
1128	          <div class="choice-main">${ch.text}${costTag}</div>
1129	          ${hintStr}
1130	        </button>
1131	      `;
1132	    })
1133	    .join("");
1134	
1135	  const overlay = document.createElement("div");
1136	  overlay.className = "modal-overlay event-modal";
1137	  overlay.innerHTML = `
1138	    <div class="modal-box event-box">
1139	      <div class="event-header">
1140	        <div class="event-icon">${evt.icon}</div>
1141	        <h2 class="event-title">${evt.title}</h2>
1142	      </div>
1143	      <p class="event-story">${evt.story}</p>
1144	      <div class="event-choices">${choicesHtml}</div>
1145	      <div style="text-align:center;margin-top:8px;font-size:10px;color:var(--text-muted);">
1146	        ⏰ 这是一个会影响数值的选择，请谨慎决定
1147	      </div>
1148	    </div>
1149	  `;
1150	  document.body.appendChild(overlay);
1151	
1152	  // 绑定选项点击
1153	  overlay.querySelectorAll(".event-choice").forEach((btn) => {
1154	    btn.addEventListener("click", () => {
1155	      const idx = parseInt(btn.dataset.idx);
1156	      const choice = evt.choices[idx];
1157	      if (!choice) return;
1158	      const state = StateManager.getState();
1159	      try {
1160	        if (typeof choice.apply === "function") {
1161	          choice.apply(state);
1162	        }
1163	      } catch (e) {
1164	        console.error("Event choice apply error:", e);
1165	      }
1166	      // 清掉待弹事件
1167	      state._pendingEvent = null;
1168	      // 关闭弹窗 + 重新渲染
1169	      document.body.removeChild(overlay);
1170	      renderAll();
1171	    });
1172	  });
1173	}
