    icon: "♻️",
    location: "slum",
    requirements: { minAge: 16, maxAge: 65 },
    effects: {
      fatigue: 22,
      hygiene: -15,
      happiness: -5,
      physiqueXp: 2,
      agilityXp: 1,
    },
    payCalc(state) {
      const base = 45 + Math.random() * 55;
      const multi = 1 + state.skills.sales.level * 0.005;
      return Math.floor(base * Math.min(multi, 2));
