 * {
 *   id, name, desc, icon,                    // 显示
 *   location: '...',                          // 需要在此地点
 *   requirements: { ... },                    // 属性/技能/年龄要求
 *   effects: { ... },                         // 执行后属性变化
 *   payCalc(state),                           // 收入计算函数（引用 state）
 *   risk: { injury, illness },                // 风险概率
 *   startupCost: 0,                           // 启动资金（可选）
 * }
 */

