176	    }
177	  }
178	  const HOUSING_NAMES = ["🌃 露宿街头", "🛏️ 合租床位", "🚪 单间", "🏠 一居室"];
179	  const houseName = HOUSING_NAMES[state.housing?.tier || 0] || HOUSING_NAMES[0];
