196	        ${state.housing?.storageRented ? " 📦 已租仓库" : ""}
197	      </div>
198	      ${state.housing?.tier < 3 ? `<div style="font-size:10px;color:var(--text-muted);margin-top:3px;">💡 去<strong style="color:var(--accent);">城中村</strong>可升级住所</div>` : ""}
199	    `;
200	  }
201	}
202	
203	/** 获取地点服务标签 */
204	function getLocationServiceBadges(locKey) {
205	  const badges = [];
206	  const loc = getLocation(locKey);
207	  if (!loc) return badges;
208	
209	  // 可租房
210	  if (locKey === "slum") {
211	    badges.push({
212	      icon: "🏠",
213	      label: "租房",
214	      bg: "rgba(46,204,113,0.1)",
215	      color: "#2ecc71",
216	    });
217	  }
218	  // 可租仓库 & 批发
219	  if (locKey === "wholesaleMarket") {
220	    badges.push({
221	      icon: "📦",
222	      label: "仓库+批发",
223	      bg: "rgba(243,156,18,0.1)",
224	      color: "#f39c12",
225	    });
226	  }
227	  // 医院
228	  if (locKey === "hospital") {
229	    badges.push({
230	      icon: "🏥",
231	      label: "看病",
232	      bg: "rgba(231,76,60,0.1)",
233	      color: "#e74c3c",
234	    });
235	  }
236	  // 银行
237	  if (locKey === "bank") {
238	    badges.push({
239	      icon: "🏦",
240	      label: "存取款",
241	      bg: "rgba(52,152,219,0.1)",
242	      color: "#3498db",
243	    });
244	  }
245	  // 培训
246	  if (locKey === "trainingCenter") {
247	    badges.push({
248	      icon: "📚",
249	      label: "学习考证",
250	      bg: "rgba(155,89,182,0.1)",
251	      color: "#9b59b6",
252	    });
253	  }
254	  // 公园
255	  if (locKey === "park") {
256	    badges.push({
257	      icon: "🌳",
258	      label: "放松",
259	      bg: "rgba(46,204,113,0.1)",
260	      color: "#2ecc71",
261	    });
262	  }
263	  // 科技园
264	  if (locKey === "techPark") {
265	    badges.push({
266	      icon: "💼",
267	      label: "应聘",
268	      bg: "rgba(0,180,216,0.1)",
269	      color: "#00b4d8",
270	    });
271	  }
272	  // 商业区
273	  if (locKey === "commercialDist") {
274	    badges.push({
275	      icon: "🛍️",
276	      label: "购物+摆摊",
277	      bg: "rgba(0,180,216,0.1)",
278	      color: "#00b4d8",
279	    });
280	  }
281	  // 工作数量
282	  if (loc.jobs && loc.jobs.length > 0) {
283	    badges.push({
284	      icon: "💼",
285	      label: loc.jobs.length + "种工作",
286	      bg: "rgba(243,156,18,0.1)",
287	      color: "#f39c12",
288	    });
289	  }
290	
291	  return badges;
292	}
293	
294	// ====== Tab Bar ======
295	function renderTabBar(state) {
296	  const tabs = document.querySelectorAll("#tab-bar .tab-btn");
297	  tabs.forEach((btn) => {
298	    btn.classList.toggle("active", btn.dataset.tab === currentTab);
299	
300	    // 某些 Tab 在特定阶段隐藏
301	    if (btn.dataset.tab === "corp" && state.player.phase !== "corporate") {
302	      btn.style.display = "none";
303	    } else if (btn.dataset.tab === "trade" && state.player.phase !== "street") {
304	      btn.style.display = "none";
305	    } else {
306	      btn.style.display = "";
307	    }
308	  });
309	}
310	
311	function switchTab(tabName) {
312	  currentTab = tabName;
313	  renderAll();
314	}
315	
316	// ====== Tab Content 渲染 ======
317	function renderCurrentTab(state) {
318	  const area = document.getElementById("content-area");
319	  area.innerHTML = "";
320	
321	  // 时间槽指示器
322	  renderTimeSlot(state, area);
323	
324	  // 活跃新闻
325	  renderActiveNews(state, area);
326	
327	  switch (currentTab) {
328	    case "actions":
329	      renderActionsTab(state, area);
330	      break;
331	    case "map":
332	      renderMapTab(state, area);
333	      break;
334	    case "trade":
335	      renderTradeTab(state, area);
336	      break;
337	    case "inventory":
338	      renderInventoryTab(state, area);
339	      break;
340	    case "skills":
341	      renderSkillsTab(state, area);
342	      break;
343	    case "corp":
344	      renderCorpTab(state, area);
345	      break;
346	    case "investment":
347	      if (typeof renderInvestmentTab === "function") renderInvestmentTab(state, area);
348	      else area.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:40px;">投资系统加载中...</p>';
349	      break;
350	    default:
351	      area.innerHTML += '<p style="color:var(--text-muted)">开发中...</p>';
352	  }
353	}
354	
355	function renderTimeSlot(state, parent) {
356	  const slotNames = {
357	    morning: "☀️ 上午",
358	    afternoon: "🌤️ 下午",
359	    evening: "🌙 晚上",
360	  };
361	  const slot = state.player.timeSlot;
362	  const div = document.createElement("div");
363	  div.id = "time-slot-indicator";
364	  const ap = state.player.actionPoints || 0;
365	  const maxAp = state.player.maxActionPoints || 100;
366	  div.innerHTML = `
367	    <span>📅 第 <strong>${state.player.day}</strong> 天</span>
368	    <span>|</span>
369	    <span class="time-slot-badge ${slot}">${slotNames[slot]}</span>
370	    <span style="font-size:11px;color:var(--text-muted);margin-left:8px;">
371	      ⚡ <strong style="color:${ap > 50 ? "var(--success)" : ap > 20 ? "var(--warning)" : "var(--danger)"};">${ap}</strong>/${maxAp}
372	    </span>
373	    <span style="margin-left:auto;font-size:11px;color:var(--text-muted)">
374	      ${state.player.phase === "corporate" ? `Q${state.player.corpQuarter}` : ""}
375	    </span>
376	  `;
377	  parent.appendChild(div);
378	}
379	
380	function renderActiveNews(state, parent) {
381	  if (state.activeNews && state.activeNews.length > 0) {
382	    for (const news of state.activeNews) {
383	      const banner = document.createElement("div");
384	      banner.className = "news-banner";
385	      banner.innerHTML = `<span class="news-icon">📰</span> ${news.headline}`;
386	      parent.appendChild(banner);
387	    }
388	  }
389	}
390	
391	// ====== Actions Tab ======
392	function renderActionsTab(state, parent) {
393	  const actions = getAvailableActions(state);
394	
395	  // 分离出行和其他行动
396	  const travelActions = actions.filter((a) => a.id.startsWith("travel_"));
397	  const housingActions = actions.filter(
398	    (a) => a.id.startsWith("housing_") || a.id.startsWith("storage_"),
399	  );
400	  const otherActions = actions.filter(
401	    (a) =>
402	      !a.id.startsWith("travel_") &&
403	      !a.id.startsWith("housing_") &&
404	      !a.id.startsWith("storage_"),
405	  );
406	
407	  // === 🌍 出行区域（置顶，醒目） ===
408	  if (travelActions.length > 0) {
409	    const travelSection = document.createElement("div");
410	    travelSection.style.cssText = "margin-bottom:16px;";
411	    travelSection.innerHTML =
412	      '<h3 style="color:var(--accent);margin-bottom:8px;font-size:14px;">🌍 出行 — 点击前往其他地点</h3>';
413	
414	    const travelGrid = document.createElement("div");
415	    travelGrid.className = "action-cards";
416	    travelGrid.style.gridTemplateColumns =
417	      "repeat(auto-fill, minmax(180px, 1fr))";
418	
419	    for (const action of travelActions) {
420	      const destKey = action.id.replace("travel_", "");
421	      const dest =
422	        typeof getLocation === "function" ? getLocation(destKey) : null;
423	      const jobCount = dest ? (dest.jobs || []).length : 0;
424	
425	      // 服务标签
426	      const badges =
427	        typeof getLocationServiceBadges === "function"
428	          ? getLocationServiceBadges(destKey)
429	          : [];
430	      const badgeStr =
431	        badges.length > 0
432	          ? badges
433	              .map(
434	                (b) =>
435	                  `<span style="font-size:9px;padding:2px 5px;border-radius:3px;background:${b.bg};color:${b.color};border:1px solid ${b.color};">${b.icon} ${b.label}</span>`,
436	              )
437	              .join(" ")
438	          : "";
439	
440	      // 检查该地点的最佳买卖机会
441	      let tradeHint = "";
442	      if (typeof GOODS !== "undefined" && state.trade.goodsPrices[destKey]) {
443	        const opportunities = [];
444	        for (const good of GOODS) {
445	          const destPrice = state.trade.goodsPrices[destKey]?.[good.id];
446	          const curPrice =
447	            state.trade.goodsPrices[state.trade.currentLocation]?.[good.id];
448	          if (destPrice && curPrice && destPrice > curPrice * 1.3) {
449	            opportunities.push(`${good.name}📈`);
450	          }
451	        }
452	        if (opportunities.length > 0)
453	          tradeHint = `<br>🤑 可卖: ${opportunities.slice(0, 2).join(" ")}`;
454	      }
455	
456	      const card = document.createElement("div");
457	      card.className = "action-card";
458	      card.style.borderColor = "var(--accent)";
459	      card.style.background =
460	        "linear-gradient(135deg, var(--bg-card), rgba(0,180,216,0.05))";
461	      card.innerHTML = `
462	        <div style="display:flex;justify-content:space-between;align-items:center;">
463	          <div class="card-title" style="font-size:15px;color:var(--accent);">${dest ? dest.name : destKey}</div>
464	          <span style="font-size:10px;color:var(--text-muted);">🚶 前往</span>
465	        </div>
466	        <div class="card-desc" style="font-size:11px;margin:4px 0;">
467	          ${dest ? dest.desc : ""}
468	          ${jobCount > 0 ? `<br>💼 ${jobCount}种工作机会` : ""}
469	          ${tradeHint}
470	        </div>
471	        ${badgeStr ? `<div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:3px;">${badgeStr}</div>` : ""}
472	      `;
473	      card.addEventListener("click", () => {
474	        action.handler();
475	        renderAll();
476	      });
477	      travelGrid.appendChild(card);
478	    }
479	    travelSection.appendChild(travelGrid);
480	    parent.appendChild(travelSection);
481	  }
482	
483	  // === 🏠 住所/仓储区域（醒目） ===
484	  if (housingActions.length > 0) {
485	    const houseSection = document.createElement("div");
486	    houseSection.style.cssText =
487	      "margin-bottom:16px;padding:12px;background:rgba(243,156,18,0.05);border:1px solid rgba(243,156,18,0.2);border-radius:var(--radius-md);";
488	    houseSection.innerHTML =
489	      '<h3 style="color:var(--warning);margin-bottom:8px;font-size:14px;">🏠 住所 & 仓储 — 提升生活质量</h3>';
490	    const houseGrid = document.createElement("div");
491	    houseGrid.className = "action-cards";
492	    houseGrid.style.gridTemplateColumns =
493	      "repeat(auto-fill, minmax(200px, 1fr))";
494	    for (const action of housingActions) {
495	      houseGrid.appendChild(createActionCard(action, state));
496	    }
497	    houseSection.appendChild(houseGrid);
498	    parent.appendChild(houseSection);
499	  }
