              "success",
            );
          } else {
            st.resources.cash = Math.max(0, st.resources.cash - 50);
            st.needs.happiness = Math.max(0, st.needs.happiness - 5);
            StateManager.addMessage(
              "📱 被识破了！还是被抢了 50 块，混混也走了。",
              "warning",
            );
          }
        },
