        );
        st.resources.totalEarned += 200;
      } else {
        StateManager.addMessage(
          "📞 和爸妈聊了 10 分钟，心情好多了。",
          "success",
        );
      }
      consumeAP(20);
    },
  });

  actions.push({
    id: "remit_home",
    name: "💌 给家里汇款",
    desc: "把一部分钱寄回老家。",
    icon: "💌",
    costEstimate: "200~1000",
    handler: () => {
      showRemitModal();
    },
  });

  actions.push({
    id: "internet_bar",
    name: "💻 网吧上网",
