      const st = StateManager.getState();
      if (st.resources.cash < 30) {
        StateManager.addMessage("💊 30 块都掏不出来。", "warning");
        return;
      }
      st.resources.cash -= 30;
      st.status.health = Math.min(100, st.status.health + 5);
