        "👕 买了一件衬衫！看起来人模人样的。卫生+10，名气+1。",
        "success",
      );
      consumeAP(20);
    },
  });

  // === 投资 / 理财类 ===
  actions.push({
    id: "lottery",
    name: "🎰 买张彩票",
    desc: "花 2 块买注彩票，搏一搏单车变摩托。",
