          st.needs.happiness = Math.min(100, st.needs.happiness + 12);
          st.status.fame = Math.min(100, st.status.fame + 3);
          StateManager.addMessage(
            "🏛️ 钱包交给了警察，警察夸你拾金不昧，心情大好！",
            "success",
          );
        },
      },
      {
        text: "🚶 当作没看见",
        hint: "怕惹麻烦",
        apply: (st) => {
          // 啥也不发生
          StateManager.addMessage("🚶 你假装没看见走了过去。", "info");
        },
      },
    ],
  },

  {
