  },
];

const PROPERTIES = [
  {
    id: "apt_old",
    name: "老破小公寓",
    type: "住宅",
    price: 500000,
    appreciation: 0.0003,
    rent: 1500,
    desc: "租售比高",
  },
  {
    id: "apt_new",
